// Inter (latin subset, weights 500 and 800), embedded so the share-card render
// never waits on a CDN. Inter is licensed under the SIL Open Font License 1.1.
// Source: fontsource inter@5, latin-500-normal.woff and latin-800-normal.woff.
// Generated once; regenerate by base64-encoding those two files.

const decode = (base64: string) => {
  const binary = atob(base64)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i)
  return bytes.buffer as ArrayBuffer
}

const INTER_500 = ''
const INTER_800 = ''

let cached: { name: string; data: ArrayBuffer; weight: 500 | 800 }[] | null =
  null

export const interFonts = () => {
  cached ??= [
    { name: 'Inter', data: decode(INTER_500), weight: 500 },
    { name: 'Inter', data: decode(INTER_800), weight: 800 },
  ]
  return cached
}
